import type { Reel } from '../../../../../reels/types';
import * as S from './scenes';

// Running example: the exact same SQL query, over identical logical data (20,000,000 rows generated by
// the same deterministic formula in both engines, never transferred between them), run on PostgreSQL
// (a Volcano-style, tuple-at-a-time executor) and DuckDB (a vectorized engine). Every number below is
// in examples.py and SOURCES.md ("Measured directly").

const reel: Reel = {
  steps: [
    {
      title: 'The same query, the same answer, two very different costs',
      body: (
        <>
          The exact same <code>SELECT ... GROUP BY</code>, over the exact same 20,000,000 rows, gives the exact same answer on two real engines. PostgreSQL,
          single-threaded: 3956.844 ms. DuckDB, single-threaded: 240.726 ms.
        </>
      ),
      duration: 4.6,
      fig: '3956.844 ms vs. 240.726 ms, same answer',
      Visual: S.TwoCosts,
    },
    {
      title: 'Predict: why would the exact same SQL cost 16.4× more on one engine?',
      body: (
        <>
          Same table, same query, same answer — checked, not assumed. Why would one engine take about 16.4 times longer than the other to produce it?
        </>
      ),
      duration: 1.8,
      fig: 'same SQL, same answer, 16.4× apart',
      predict: {
        options: [
          { label: 'Different hardware' },
          { label: 'A smarter query plan on the faster engine' },
          { label: 'The same kind of plan, run very differently', correct: true },
        ],
        explain: (
          <>
            The same kind of plan, run very differently — both engines pick a scan, a filter and a group-by. What differs is how many rows move through
            each operator on every single step of getting there.
          </>
        ),
      },
      Visual: S.PredictWhyGap,
    },
    {
      title: 'Reveal: the Volcano iterator',
      body: (
        <>
          PostgreSQL's executor pulls one row at a time up through the whole plan: the aggregate asks the scan for a row, gets one row, asks again. Every
          operator, every row, one at a time, top to bottom.
        </>
      ),
      duration: 4.4,
      fig: 'pull one row, all the way up, every row',
      Visual: S.RevealVolcano,
    },
    {
      title: 'How the iterator model actually runs',
      body: (
        <>
          Pulling one row at a time means calling a function, once, for every operator, for every row — 19,587,629 rows through a scan, a filter and a
          hash table, one function call at a time. That cost is interpretation overhead, and it also hides any chance for the compiler to parallelize the
          work across rows.
        </>
      ),
      duration: 4.8,
      fig: 'one function call, per operator, per row',
      Visual: S.HowIteratorRuns,
    },
    {
      title: 'Reveal: vectorization',
      body: (
        <>
          DuckDB's operators don't take one row — they take an array of them. Its default batch, a <code>vector</code>, holds 2048 rows at once; the
          research engine that introduced this idea defaulted to 1024.
        </>
      ),
      duration: 4.4,
      fig: '2048 rows per operator call, not 1',
      Visual: S.RevealVectorization,
    },
    {
      title: 'How a vectorized operator actually works',
      body: (
        <>
          Instead of a function call per row, a vectorized operator runs one tight loop over an array of rows already sitting in cache. Same filter, same
          multiply, same 19,587,629 rows — just looped over in batches instead of summoned one function call at a time.
        </>
      ),
      duration: 4.4,
      fig: 'one loop over a cache-sized array',
      Visual: S.HowVectorizedRuns,
    },
    {
      title: 'Predict: is a bigger batch always faster?',
      body: (
        <>
          If 2048 rows per call beats 1, would an even bigger batch — the whole table in one call — beat 2048?
        </>
      ),
      duration: 1.8,
      fig: 'bigger batch, faster — always?',
      predict: {
        options: [{ label: 'Yes, bigger is always faster' }, { label: 'No — there’s a sweet spot', correct: true }, { label: 'Batch size doesn’t matter' }],
        explain: (
          <>
            No — there's a sweet spot. A batch has to fit the CPU cache it's processed in; past that point, bigger stops helping and starts hurting.
          </>
        ),
      },
      Visual: S.PredictBiggerBatch,
    },
    {
      title: 'Reveal: the sweet spot',
      body: (
        <>
          On the research engine's own benchmark, a batch of 1 row was as slow as a row-at-a-time interpreter. The best size measured around 1000, and
          anything from 128 to 8000 worked well — past that, the batch no longer fit the cache, and performance fell off again.
        </>
      ),
      duration: 4.8,
      fig: '1 row: slow. ~1000: best. past 8000: worse again.',
      takeaway: 'A batch has to fit the cache it runs in — too small reintroduces overhead, too large blows the cache.',
      Visual: S.RevealSweetSpot,
    },
    {
      title: 'How compiling goes further than vectorizing',
      body: (
        <>
          A compiled engine blurs the operators themselves away: a scan, a filter and a hash build become one piece of generated machine code, with values
          staying in CPU registers instead of being written into an array between each step. Data is pushed forward through that code, not pulled.
        </>
      ),
      duration: 4.8,
      fig: 'scan + filter + build → one code fragment',
      Visual: S.HowCompilingGoesFurther,
    },
    {
      title: 'Predict: iterator, vectorized, or compiled — which wins on one core?',
      body: (
        <>
          Three ways to run the same plan on a single core: pull one row at a time, process a cache-sized batch at a time, or compile the whole pipeline to
          machine code. Which is fastest?
        </>
      ),
      duration: 2,
      fig: 'iterator vs. vectorized vs. compiled',
      predict: {
        options: [
          { label: 'The iterator — it’s the simplest' },
          { label: 'Vectorized — it’s the modern default' },
          { label: 'Compiled — it removes the most overhead', correct: true },
        ],
        explain: (
          <>
            Compiled — removing both the per-row function call and the per-batch materialization leaves the least overhead of the three. But that result
            comes with a real cost of its own.
          </>
        ),
      },
      Visual: S.PredictThreeModels,
    },
    {
      title: 'Reveal: the real trade-off is compile latency and debuggability',
      body: (
        <>
          The research system that pioneered this reported hand-written C++ and its compiled engine landing close together, both far ahead of a classical
          iterator — but every query first has to be compiled to machine code before its first row comes out, and a crash inside generated code is harder
          to read than one inside a plain interpreter loop.
        </>
      ),
      duration: 4.8,
      fig: 'fastest to run, slowest to start debugging',
      takeaway: 'Compiling wins on raw speed, but pays for it in compile latency before the first row and in debuggability.',
      Visual: S.RevealTradeoff,
    },
    {
      title: 'Morsel-driven parallelism',
      body: (
        <>
          Instead of fixing how many threads run a query before it starts, split the work into small morsels and hand them to idle threads as they finish
          the last one. Measured here: DuckDB went from 240.726 ms on 1 thread to 72.693 ms on 4 — about 3.3× — the same kind of scaling the research
          system that introduced morsels reported at a much larger scale.
        </>
      ),
      duration: 5,
      fig: '240.726 ms (1 thread) → 72.693 ms (4 threads)',
      takeaway: 'Splitting work into morsels at run time scales with however many cores a machine actually has.',
      Visual: S.MorselDriven,
    },
    {
      title: 'Recap',
      body: (
        <>
          Pulling one row at a time costs a function call per row. A vectorized batch amortizes that call, if it fits the cache. Compiling removes the
          batch too, at the cost of compile time and debuggability. And a fixed thread count is just another plan-time decision morsels replace with a
          run-time one.
        </>
      ),
      duration: 4.8,
      fig: 'four ideas, one running example',
      Visual: S.Recap,
    },
    {
      title: 'Prove it · 1 of 2',
      body: (
        <>
          An engine's own plan reports one operator's row count as "~4,000,000 rows" for a whole stage, not once per row. Is this engine pulling
          tuple-at-a-time, or working in batches?
        </>
      ),
      duration: 2.4,
      fig: 'read the row-count granularity',
      predict: {
        options: [{ label: 'Tuple-at-a-time' }, { label: 'Working in batches', correct: true }],
        explain: (
          <>
            Working in batches — a plan that reports one count for a whole stage, rather than one entry per row, is accounting for arrays of rows, not
            single ones at a time.
          </>
        ),
      },
      Visual: S.ProveBatchSignal,
    },
    {
      title: 'Prove it · 2 of 2',
      body: (
        <>
          One engine's time drops from 240.726 ms on 1 thread to 72.693 ms on 4. Is that closer to morsel-driven, elastic scaling, or a fixed, static
          split of the work?
        </>
      ),
      duration: 2.4,
      fig: '1 thread → 4 threads, ~3.3×',
      predict: {
        options: [{ label: 'A fixed static split' }, { label: 'Elastic, morsel-driven scaling', correct: true }],
        explain: (
          <>
            Elastic, morsel-driven scaling — close to linear across the cores actually available, which is exactly the property a fixed, plan-time thread
            count wouldn't give you on a machine with a different core count.
          </>
        ),
      },
      Visual: S.ProveScaling,
    },
  ],
};

export default reel;
